// One booking request per execution. Cleans the form fields, checks the basics,
// and builds the attribution object from whatever the form captured.
const body = $input.first().json.body || {};
const s = v => (v === undefined || v === null) ? '' : String(v).trim();
const email = s(body.email).toLowerCase();
const first_name = s(body.first_name || body.firstName).slice(0, 80);
const last_name = s(body.last_name || body.lastName).slice(0, 80);
const phone = s(body.phone).replace(/[^\d+]/g, '').slice(0, 20);
const meeting_type = s(body.meeting_type).toLowerCase() || 'discovery';
const errors = [];
if (s(body.website)) errors.push('spam');            // honeypot: humans leave it empty
if (!first_name) errors.push('first_name');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) errors.push('email');
const keys = ['utm_source','utm_medium','utm_campaign','utm_content','utm_term',
              'gclid','gbraid','wbraid','fbclid','ttclid','msclkid','landing_url','referrer'];
const attribution = {};
for (const k of keys) { const v = s(body[k]); if (v) attribution[k] = v.slice(0, 250); }
const booking_key = s(body.booking_key).slice(0, 40)
  || ('bk_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8));
return [{ json: {
  valid: errors.length === 0,
  errors,
  first_name, last_name, email, phone, meeting_type,
  need: s(body.need).slice(0, 1000),
  consent: body.consent === true || s(body.consent) === 'true' || s(body.consent) === 'on',
  attribution,
  booking_key,
  received_at: new Date().toISOString(),
}}];

// EDIT THIS NODE. Everything site-specific lives here.
const settings = {
  capsule_base: 'https://api.capsulecrm.com/api/v2',
  pipeline_name: 'Enquiries',          // the Capsule pipeline bookings land in
  new_milestone_name: 'New',           // milestone for a brand-new enquiry
  tags: ['form:booking'],              // tags applied to every person and opportunity this creates
  attribution_tag: 'Attribution',      // the DataTag that owns the fields below (capsule/SCHEMA.md)
  // Names of the text fields inside that DataTag. Leave the list empty until the DataTag exists;
  // the attribution still goes into the note either way.
  attribution_fields: [
    // 'utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'gclid', 'fbclid', 'landing_url', 'booking_key',
  ],
  meeting_types: {
    discovery: { label: 'Discovery call (15 min)' },
    strategy:  { label: 'Strategy session (30 min)' },
  },
  // One entry per person who takes bookings. booking_pages are the Google appointment
  // schedule links. Share > Website embed gives the long calendar.google.com form, which
  // is the one that loads inside the iframe on your page.
  hosts: [
    { name: 'Host One', email: 'one@example.co.nz',
      booking_pages: {
        discovery: 'https://calendar.google.com/calendar/appointments/schedules/REPLACE_ONE_DISCOVERY',
        strategy:  'https://calendar.google.com/calendar/appointments/schedules/REPLACE_ONE_STRATEGY',
      } },
    // { name: 'Host Two', email: 'two@example.co.nz', booking_pages: { discovery: '...', strategy: '...' } },
  ],
};
return $input.all().map(i => ({ json: { ...i.json, settings } }));

// Round robin per meeting type. The counter lives in workflow static data, so it
// survives between executions. Hosts without a page for this type are skipped.
const lead = $input.first().json;
const st = lead.settings;
const types = Object.keys(st.meeting_types);
const type = st.meeting_types[lead.meeting_type] ? lead.meeting_type : types[0];
const eligible = st.hosts.filter(h => h.booking_pages && h.booking_pages[type]);
if (!eligible.length) throw new Error(`No host has a booking page for meeting type "${type}". Check the Settings node.`);
const sd = $getWorkflowStaticData('global');
sd.round_robin = sd.round_robin || {};
const n = sd.round_robin[type] || 0;
const host = eligible[n % eligible.length];
sd.round_robin[type] = (n + 1) % eligible.length;
return [{ json: {
  ...lead,
  meeting_type: type,
  meeting_label: st.meeting_types[type].label,
  host: { name: host.name, email: host.email },
  booking_url: host.booking_pages[type],
}}];

// Capsule search is fuzzy, so we insist on an exact email match before reusing a person.
const lead = $('Pick host and booking page').first().json;
const res = $input.first().json || {};
const parties = Array.isArray(res.parties) ? res.parties : [];
const match = parties.find(p => (p.emailAddresses || []).some(e => (e.address || '').toLowerCase() === lead.email));
const st = lead.settings;
const tags = [...st.tags, `booking:${lead.meeting_type}`];
if (lead.attribution.utm_source) tags.push(('src:' + lead.attribution.utm_source).slice(0, 50));
const values = { ...lead.attribution, booking_key: lead.booking_key };
// Capsule accepts a field by name when the DataTag it belongs to is named alongside it.
const fields = (st.attribution_fields || [])
  .filter(name => values[name])
  .map(name => ({ definition: { name, tag: st.attribution_tag }, value: String(values[name]).slice(0, 250) }));
if (fields.length && st.attribution_tag) tags.push(st.attribution_tag);
const unique = [...new Set(tags)];
const create_body = { party: {
  type: 'person',
  firstName: lead.first_name,
  lastName: lead.last_name || undefined,
  emailAddresses: [{ type: 'Work', address: lead.email }],
  phoneNumbers: lead.phone ? [{ type: 'Mobile', number: lead.phone }] : undefined,
  tags: unique.map(name => ({ name })),
  fields: fields.length ? fields : undefined,
}};
return [{ json: { ...lead, party_id: match ? match.id : null, tags: unique, create_body, search_failed: !!res.error } }];

// Reached from both branches: an existing match, or the person Capsule just created.
const base = $('Match person by email').first().json;
const inp = $input.first().json || {};
const party_id = base.party_id || (inp.party && inp.party.id) || null;
if (!party_id) throw new Error('No Capsule person id. Response was: ' + JSON.stringify(inp).slice(0, 300));
return [{ json: { ...base, party_id, person_created: !base.party_id } }];

// Reuse the newest open opportunity in the pipeline, otherwise prepare a new one.
const lead = $('Resolve person').first().json;
const st = lead.settings;
const opps = ($('Capsule: list opportunities').first().json || {}).opportunities || [];
const milestones = ($input.first().json || {}).milestones || [];
const inPipeline = m => !m.pipeline || !st.pipeline_name
  || (m.pipeline.name || '').toLowerCase() === st.pipeline_name.toLowerCase();
const pipelineMs = milestones.filter(inPipeline);
const newMs = pipelineMs.find(m => (m.name || '').toLowerCase() === st.new_milestone_name.toLowerCase()) || pipelineMs[0];
const ids = new Set(pipelineMs.map(m => m.id));
const open = opps
  .filter(o => !o.closedOn && (!o.milestone || ids.size === 0 || ids.has(o.milestone.id)))
  .sort((a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')))[0];
if (!open && !newMs) throw new Error(`No milestone "${st.new_milestone_name}" found in pipeline "${st.pipeline_name}". Create the pipeline first (capsule/SCHEMA.md).`);
const attr = Object.entries(lead.attribution).map(([k, v]) => `${k}: ${v}`).join('\n');
const note = [
  `Booking requested: ${lead.meeting_label}`,
  `Host offered: ${lead.host.name}`,
  lead.need ? `What they need: ${lead.need}` : null,
  `Booking key: ${lead.booking_key}`,
  attr ? `Attribution:\n${attr}` : 'Attribution: nothing captured',
  `Received: ${lead.received_at}`,
].filter(Boolean).join('\n');
const name = `${lead.first_name} ${lead.last_name}`.trim() + ` - ${lead.meeting_label}`;
return [{ json: {
  ...lead,
  opportunity_id: open ? open.id : null,
  create_opportunity: !open,
  opportunity_create_body: open ? null : { opportunity: {
    party: { id: lead.party_id },
    name: name.slice(0, 100),
    milestone: { id: newMs.id },
    tags: lead.tags.map(t => ({ name: t })),
  } },
  note,
}}];

// Reached from both branches: the open opportunity we found, or the one just created.
const base = $('Decide opportunity').first().json;
const inp = $input.first().json || {};
const opportunity_id = base.opportunity_id || (inp.opportunity && inp.opportunity.id) || null;
if (!opportunity_id) throw new Error('No Capsule opportunity id. Response was: ' + JSON.stringify(inp).slice(0, 300));
return [{ json: { ...base, opportunity_id } }];
